const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const hw = h => ((h%360)+360)%360;
const clamp = (v,a,b) => v<a?a:(v>b?b:v);

const scl = P.scale;
const gh = u*0.72*scl, pw = u*0.50*scl;
const cx = P.x*width, by = P.y*height, top = by - gh;
const pW = pw*0.085;                    // pillar half-width
const Lx = cx - pw/2, Rx = cx + pw/2;   // pillar centers
const kasY = top + gh*0.06;             // top curved beam center
const nukY = top + gh*0.28;             // second beam center
const over = pw*0.16;                   // kasagi overhang

// ---- style table ----
const V = hw(P.hue);
const STY = {
  vermilion: { wood:[V,70,76], woodD:[V,80,42], cap:[0,0,10], plaque:[44,66,86], mode:'lacquer', ink:false, wire:false, wood2:[V,60,90] },
  sumi:      { wood:[220,6,20], woodD:[220,8,8], cap:[0,0,6], plaque:[220,4,44], mode:'ink', ink:true, wire:false, wood2:[220,5,40] },
  woodblock: { wood:[V,72,80], woodD:[0,0,8], plaque:[44,70,84], cap:[0,0,8], mode:'block', ink:false, wire:false, wood2:[V,50,94] },
  blueprint: { wood:[196,64,74], woodD:[210,72,16], plaque:[192,55,60], cap:[196,50,50], mode:'wire', ink:false, wire:true, wood2:[196,40,90] },
  twilight:  { wood:[hw(V+8),34,46], woodD:[230,40,16], plaque:[40,30,58], cap:[230,20,20], mode:'lacquer', ink:false, wire:false, wood2:[hw(V+8),24,64] }
};
const sty = STY[P.style] || STY.vermilion;

// ---- cached gate structure ----
const key = width+'x'+height+':'+scl.toFixed(3)+':'+Math.round(P.hue)+':'+P.style+':'+P.seed;
if (!S.gfx || S.key !== key) {
  const g = S.gfx || (S.gfx = createGraphics(width, height));
  g.colorMode(HSB,360,100,100,100);
  g.clear(); g.push();

  const roughRect = (x0,y0,w,h,base,dark) => {
    // ink dry-brush block: layered translucent strokes with broken edges
    for (let l=0;l<5;l++){
      const a = 22 + l*10;
      g.noStroke(); g.fill(base[0],base[1],clamp(base[2]-l*3,0,100), a);
      const jx = (fr(x0*0.7+l*3.3)-0.5)*w*0.05, jy=(fr(y0*0.9+l)-0.5)*h*0.03;
      g.rect(x0+jx, y0+jy, w, h);
    }
    // dry-brush streaks
    g.stroke(dark[0],dark[1],dark[2],40); g.strokeWeight(Math.max(1,u*0.003));
    for (let i=0;i<7;i++){ const yy=y0+ (i+ .5)/7*h; g.line(x0+w*0.04, yy, x0+w*0.96, yy+ (fr(i+x0)-0.5)*u*0.01); }
  };
  const beam = (x0,x1,yc,h) => {
    if (sty.ink) { roughRect(x0, yc-h/2, x1-x0, h, sty.wood, sty.woodD); return; }
    if (sty.wire){ g.noFill(); g.stroke(sty.wood[0],sty.wood[1],sty.wood[2]); g.strokeWeight(Math.max(1.2,u*0.004)); g.rect(x0,yc-h/2,x1-x0,h); return; }
    // lacquer / block: base + top-lit band + shadow underside + keyline
    g.noStroke();
    g.fill(sty.woodD[0],sty.woodD[1],sty.woodD[2]); g.rect(x0,yc-h/2,x1-x0,h);
    g.fill(sty.wood[0],sty.wood[1],sty.wood[2]); g.rect(x0,yc-h/2,x1-x0,h*0.62);
    g.fill(sty.wood2[0],sty.wood2[1],sty.wood2[2],70); g.rect(x0,yc-h/2,x1-x0,h*0.16);
    if (sty.mode==='block'){ g.noFill(); g.stroke(0,0,8); g.strokeWeight(Math.max(1.4,u*0.005)); g.rect(x0,yc-h/2,x1-x0,h); }
  };

  // pillars (slight taper: wider at base)
  const pillar = (xc) => {
    const wB = pW*2.15, wT = pW*1.9;
    if (sty.ink){ roughRect(xc-wB/2, nukY, wB, by-nukY, sty.wood, sty.woodD); return; }
    if (sty.wire){ g.noFill(); g.stroke(sty.wood[0],sty.wood[1],sty.wood[2]); g.strokeWeight(Math.max(1.2,u*0.004));
      g.quad(xc-wT/2,nukY-gh*0.02, xc+wT/2,nukY-gh*0.02, xc+wB/2,by, xc-wB/2,by); return; }
    g.noStroke();
    g.fill(sty.woodD[0],sty.woodD[1],sty.woodD[2]); g.quad(xc-wT/2,top, xc+wT/2,top, xc+wB/2,by, xc-wB/2,by);
    g.fill(sty.wood[0],sty.wood[1],sty.wood[2]); g.quad(xc-wT/2,top, xc+wT*0.15,top, xc+wB*0.15,by, xc-wB/2,by);
    g.fill(sty.wood2[0],sty.wood2[1],sty.wood2[2],55); g.rect(xc-wT/2, top, wT*0.18, by-top);
    if (sty.mode==='block'){ g.noFill(); g.stroke(0,0,8); g.strokeWeight(Math.max(1.4,u*0.005)); g.quad(xc-wT/2,top, xc+wT/2,top, xc+wB/2,by, xc-wB/2,by); }
  };

  // bokashi sky wash for woodblock behind the gate
  if (sty.mode==='block'){
    for (let i=0;i<40;i++){ const f=i/39; g.noStroke(); g.fill(hw(V+20), 30*(1-f)+8, 30+f*40, 8); g.rect(cx-pw*0.9, top-gh*0.05+f*(gh*0.5), pw*1.8, gh*0.5/40+1); }
  }

  pillar(Lx); pillar(Rx);
  // nuki (lower straight beam) — extends beyond pillars
  beam(Lx-pW*1.6, Rx+pW*1.6, nukY, gh*0.075);
  // gakuzuka strut + plaque
  if (!sty.wire){ g.noStroke(); g.fill(sty.woodD[0],sty.woodD[1],sty.woodD[2]); g.rect(cx-pW*0.5, kasY+gh*0.03, pW, nukY-kasY-gh*0.03); }
  // plaque
  if (sty.ink){ roughRect(cx-pw*0.10, kasY+gh*0.05, pw*0.20, gh*0.14, sty.plaque, sty.woodD); }
  else if (sty.wire){ g.noFill(); g.stroke(sty.plaque[0],sty.plaque[1],sty.plaque[2]); g.rect(cx-pw*0.10, kasY+gh*0.05, pw*0.20, gh*0.14); }
  else { g.noStroke(); g.fill(sty.plaque[0],sty.plaque[1],sty.plaque[2]*0.7); g.rect(cx-pw*0.10, kasY+gh*0.05, pw*0.20, gh*0.14, u*0.006);
         g.fill(sty.plaque[0],sty.plaque[1],sty.plaque[2]); g.rect(cx-pw*0.085, kasY+gh*0.065, pw*0.17, gh*0.11, u*0.004);
         g.stroke(0,0,10,50); g.strokeWeight(Math.max(1,u*0.004)); g.line(cx-pw*0.04, kasY+gh*0.08, cx-pw*0.04, kasY+gh*0.155); g.line(cx+pw*0.02, kasY+gh*0.075, cx+pw*0.02, kasY+gh*0.16); }

  // shimagi (thin flat beam just under kasagi)
  beam(cx-pw/2-over*0.8, cx+pw/2+over*0.8, kasY+gh*0.055, gh*0.03);
  // kasagi (top beam) — curved with upturned ends, drawn as a shape
  const drawKasagi = () => {
    const y = kasY, h = gh*0.06, x0 = cx-pw/2-over, x1 = cx+pw/2+over;
    if (sty.wire){ g.noFill(); g.stroke(sty.wood[0],sty.wood[1],sty.wood[2]); g.strokeWeight(Math.max(1.2,u*0.004)); }
    else { g.noStroke(); g.fill(sty.ink?sty.wood[0]:sty.woodD[0], sty.ink?sty.wood[1]:sty.woodD[1], sty.ink?sty.wood[2]:sty.woodD[2], sty.ink?70:100); }
    const sag = gh*0.035;
    g.beginShape();
    g.vertex(x0, y-h*0.5 - sag*0.4);
    g.bezierVertex(x0+ (x1-x0)*0.3, y-h*0.5+sag, cx-(x1-x0)*0.1, y-h*0.5+sag, cx, y-h*0.5+sag);
    g.bezierVertex(cx+(x1-x0)*0.1, y-h*0.5+sag, x1-(x1-x0)*0.3, y-h*0.5+sag, x1, y-h*0.5 - sag*0.4);
    g.vertex(x1, y+h*0.5 - sag*0.2);
    g.bezierVertex(x1-(x1-x0)*0.3, y+h*0.5+sag*1.2, cx+(x1-x0)*0.1, y+h*0.5+sag*1.2, cx, y+h*0.5+sag*1.2);
    g.bezierVertex(cx-(x1-x0)*0.1, y+h*0.5+sag*1.2, x0+(x1-x0)*0.3, y+h*0.5+sag*1.2, x0, y+h*0.5 - sag*0.2);
    g.endShape(CLOSE);
    if (!sty.ink && !sty.wire){ g.noStroke(); g.fill(sty.wood[0],sty.wood[1],sty.wood[2]); g.beginShape();
      g.vertex(x0, y-h*0.5-sag*0.4);
      g.bezierVertex(x0+(x1-x0)*0.3,y-h*0.5+sag, cx-(x1-x0)*0.1,y-h*0.5+sag, cx,y-h*0.5+sag);
      g.bezierVertex(cx+(x1-x0)*0.1,y-h*0.5+sag, x1-(x1-x0)*0.3,y-h*0.5+sag, x1,y-h*0.5-sag*0.4);
      g.vertex(x1,y); g.bezierVertex(cx+(x1-x0)*0.1,y+sag*0.4, cx-(x1-x0)*0.1,y+sag*0.4, x0,y); g.endShape(CLOSE);
      if (sty.mode==='block'){ g.noFill(); g.stroke(0,0,8); g.strokeWeight(Math.max(1.4,u*0.005));
        g.beginShape();
        g.vertex(x0, y-h*0.5-sag*0.4);
        g.bezierVertex(x0+(x1-x0)*0.3,y-h*0.5+sag, cx-(x1-x0)*0.1,y-h*0.5+sag, cx,y-h*0.5+sag);
        g.bezierVertex(cx+(x1-x0)*0.1,y-h*0.5+sag, x1-(x1-x0)*0.3,y-h*0.5+sag, x1,y-h*0.5-sag*0.4);
        g.vertex(x1, y+h*0.5-sag*0.2);
        g.bezierVertex(x1-(x1-x0)*0.3,y+h*0.5+sag*1.2, cx+(x1-x0)*0.1,y+h*0.5+sag*1.2, cx,y+h*0.5+sag*1.2);
        g.bezierVertex(cx-(x1-x0)*0.1,y+h*0.5+sag*1.2, x0+(x1-x0)*0.3,y+h*0.5+sag*1.2, x0,y+h*0.5-sag*0.2);
        g.endShape(CLOSE); }
    }
  };
  drawKasagi();
  g.pop();
  S.key = key;
  // rope anchor geometry stored
  S.ropeY = nukY + gh*0.04;
  S.ropeX0 = Lx + pW*1.4; S.ropeX1 = Rx - pW*1.4;
}

image(S.gfx, 0, 0);

// ---- act ----
let flutterMul=1, mistMul=1, glowMul=1;
if (P.act==='storm'){ flutterMul=2.2; mistMul=1.5; glowMul=0.9; }
else if (P.act==='dawn'){ flutterMul=0.6; mistMul=0.7; glowMul=1.2; }

const wind = Math.sin(K.t*0.5)*0.6 + Math.sin(K.t*1.7+1.3)*0.4 + K.pulse*0.5 + A.lowmid*0.7;
const breath = 0.5 + 0.5*K.swell;

// ---- drifting mist (continuous K.t scroll) ----
push(); blendMode(SCREEN); noStroke();
const NM = Math.round(4 + P.mist*mistMul*7);
for (let i=0;i<NM;i++){
  const spd = (0.02+fr(i*3.1)*0.05)*P.speed*mistMul;
  const bx = (fr(i*7.7) + K.t*spd) % 1.3 - 0.15;
  const mx = bx*(width*1.2) - width*0.1;
  const my = top + gh*(0.25+fr(i*2.2)*0.7) + Math.sin(K.t*0.4+i)*u*0.02;
  const mw = u*(0.25+fr(i*5.5)*0.35), mh = u*(0.05+fr(i*4.4)*0.05);
  const a = clamp((6 + P.mist*10)*mistMul, 0, 22);
  fill(hw(V+ (sty.ink?200:30)), sty.ink?4:18, sty.ink?70:88, a);
  ellipse(mx, my, mw, mh);
}
blendMode(BLEND); pop();

// ---- shimenawa rope + fluttering shide ----
const ropeY = S.ropeY!=null?S.ropeY:(nukY+gh*0.04);
const rx0 = S.ropeX0!=null?S.ropeX0:(Lx+pW*1.4), rx1 = S.ropeX1!=null?S.ropeX1:(Rx-pW*1.4);
const ropeSag = gh*0.05*(1+wind*0.15);
push();
// rope (catenary)
noFill();
stroke(sty.ink?[220,5,30][0]:44, sty.ink?6:36, sty.ink?36:60);
strokeWeight(Math.max(2.5,u*0.011));
beginShape();
for (let i=0;i<=16;i++){ const f=i/16; const rxp=rx0+(rx1-rx0)*f; const ry=ropeY+Math.sin(f*Math.PI)*ropeSag; vertex(rxp,ry); }
endShape();
strokeWeight(Math.max(1,u*0.004)); stroke(sty.ink?220:44, sty.ink?4:20, sty.ink?52:82,60);
beginShape();
for (let i=0;i<=16;i++){ const f=i/16; const rxp=rx0+(rx1-rx0)*f; const ry=ropeY+Math.sin(f*Math.PI)*ropeSag - u*0.004; vertex(rxp,ry); }
endShape();

// shide zigzag paper streamers hanging from rope
const NS = Math.round(3 + P.density*6);
for (let i=0;i<NS;i++){
  const f = (i+0.5)/NS;
  const ax = rx0+(rx1-rx0)*f;
  const ayy = ropeY+Math.sin(f*Math.PI)*ropeSag;
  const len = gh*(0.14+fr(i*2.7)*0.05);
  const phase = fr(i*9.1)*TAU;
  const sway = (wind*flutterMul)*(0.6+fr(i*1.3)*0.8);
  push(); translate(ax, ayy);
  const segs = 5, sw = u*(0.018+fr(i*3.3)*0.006);
  noStroke();
  for (let s=0;s<segs;s++){
    const t0=s/segs, t1=(s+1)/segs;
    const bend = Math.sin(K.t*2.4*P.speed + phase + s*0.7)*sway*u*0.03*(t0+0.3);
    const x0=Math.sin(phase+s*0.5)*sway*u*0.01 + bend*0.3;
    const y0=len*t0, y1=len*t1;
    const dir = s%2? 1:-1;
    const bl = sty.ink? (s%2? [220,4,72]:[220,3,58]) : (sty.mode==='block'? [0,0,98]:[44,8,97]);
    fill(bl[0],bl[1],bl[2], 92);
    quad(x0-sw*0.5+bend, y0, x0+sw*0.5+bend, y0, x0+sw*0.5+dir*sw*0.7+bend, y1, x0-sw*0.5+dir*sw*0.7+bend, y1);
    // fold shadow
    fill(0,0, sty.ink?10:18, 22); quad(x0+dir*sw*0.1+bend, y0, x0+sw*0.5+bend, y0, x0+sw*0.5+dir*sw*0.7+bend, y1, x0+dir*sw*0.2+dir*sw*0.7+bend, y1);
  }
  pop();
}
pop();

// ---- hanging paper lantern (chochin) breathing glow ----
push();
const lyBase = nukY + gh*0.10;
const lx = cx + Math.sin(K.t*0.7)*pw*0.02;
const ly = lyBase + Math.sin(K.t*0.9)*u*0.006;
const lw = u*0.085*scl, lh = u*0.12*scl;
const flick = 1 + (fr(Math.floor(K.t*7))-0.5)*0.12;
const gI = (P.glow*glowMul)*breath*flick + A.bass*0.3;
// glow halo
blendMode(SCREEN); noStroke();
for (let i=0;i<3;i++){ fill(28, 60, 100, clamp((10+gI*20)*(1-i/3),0,40)); ellipse(lx, ly, lw*(1.8+i*1.3), lh*(1.6+i*1.2)); }
blendMode(BLEND);
// lantern body
const lb = sty.ink? [30,30,70] : [30, 62, 78+gI*18];
drawingContext.shadowBlur = 8+gI*22; drawingContext.shadowColor='hsla(30,80%,60%,0.8)';
noStroke(); fill(lb[0],lb[1],clamp(lb[2],0,100)); ellipse(lx, ly, lw, lh);
drawingContext.shadowBlur=0;
// ribs
stroke(0,0,20,55); strokeWeight(Math.max(1,u*0.003)); noFill();
for (let i=1;i<5;i++){ const yy=ly-lh/2+lh*i/5; const wwv = lw*Math.sin((i/5)*Math.PI); line(lx-wwv/2, yy, lx+wwv/2, yy); }
// top & bottom caps
noStroke(); fill(0,0,15); rect(lx-lw*0.22, ly-lh*0.55, lw*0.44, lh*0.08, u*0.004); rect(lx-lw*0.18, ly+lh*0.47, lw*0.36, lh*0.07, u*0.004);
// inner warm core
blendMode(SCREEN); fill(40,50,100, 30+gI*30); ellipse(lx, ly, lw*0.5, lh*0.55); blendMode(BLEND);
pop();

blendMode(BLEND);
